static void em_inject_cancel(
    const rule_info_t *rule, int verdict, uint64_t timestamp,
    uint64_t counter, const mmt_array_t * const trace) {
    uint16_t cancel_cmd = 0x0FFF; // C-CANCEL command
    replace_dicom_attribute(701, 14, &cancel_cmd, 0);
    forward_packet();
}
